// 1. PROFILE: async-profiler (CPU + allocation flame graphs) or JFR in production.
//    jcmd <pid> JFR.start; jfr print --events jdk.ExecutionSample recording.jfr

// 3. ONE CHANGE at the measured hotspot. The usual Java wins:
//    - avoid boxing in a hot generic (primitive-specialise the collection)
//    - make a call site MONOMORPHIC (the JIT inlines only at one receiver type)
//    - avoid a lambda/iterator allocation per loop iteration
//    - layout: double[] streams, Double[] is a pointer chase
//    static double sum(double[] a) { double s = 0; for (double x : a) s += x; return s; }

// 4. VERIFY with JMH - the warm-up and forking exist because the JIT tiers the
//    method (interpreted -> C1 -> C2); a benchmark without warm-up measures the
//    INTERPRETER, and in-JVM micro-benchmarks are measuring the compiler itself.
@BenchmarkMode(Mode.AverageTime)
@OutputTimeUnit(TimeUnit.NANOSECONDS)
@Warmup(iterations = 5)
@Fork(2)
@State(Scope.Benchmark)
public class SumBench {
    private double[] data = new double[1 << 16];
    @Benchmark public double loop() { double s = 0; for (double x : data) s += x; return s; }
}
/* 5. GUARD: keep the JMH benchmark (or an integration perf test) in CI.
 * Also: -XX:+PrintEscapeAnalysis - if escape analysis succeeds, an
 * allocation disappears entirely - layout is often the lever. */
